# Shared helpers for the dataset integrity and manifest tests.

# Packaged objects that are infrastructure rather than democracy datasets, and
# so are excluded from the structural checks in test-dataset-integrity.R.
infrastructure_objects <- c("bibliography", "democracy_info")

# Packaged datasets that are generated by this package itself rather than
# archived from an external source, and so have no row in democracy_info.
registry_exempt_datasets <- c(infrastructure_objects, "extended_uds")

# Split the comma-separated keys in democracy_info$dataset (e.g.
# "pacl, pacl_update") into one row per key.
registry_with_keys <- function(info = democracyData::democracy_info) {
  info |>
    dplyr::mutate(key = strsplit(dataset, ",\\s*")) |>
    tidyr::unnest("key")
}

# Map a packaged dataset name to its key in democracy_info$dataset. Exact
# matches win; otherwise release-year, _extended, and _pmm suffixes are
# stripped and known renames applied.
registry_key_for_dataset <- function(
  dataset_name,
  known_keys = registry_with_keys()$key
) {
  special_cases <- c(
    polity5 = "polity_annual",
    polity_pmm = "polityIV",
    prc_pmm = "prc_gasiorowski",
    wgi = "wgi_democracy",
    wgi_legacy = "wgi_democracy",
    vdem_simple = "vdem",
    REIGN = "reign",
    pitf_p4 = "pitf"
  )

  if (dataset_name %in% names(special_cases)) {
    return(unname(special_cases[[dataset_name]]))
  }

  if (dataset_name %in% known_keys) {
    return(dataset_name)
  }

  base_name <- sub("_(extended|pmm|\\d{4})$", "", dataset_name)
  base_name <- sub("^gwf_(all|autocratic)$", "gwf", base_name)
  base_name
}
